.tutor { padding: .4rem .6rem; border-radius: 6px; font-size: .75rem; }
.tutor.info { background: rgba(91,141,184,.1); color: #5B8DB8; }
.tutor.warn { background: rgba(245,158,11,.1); color: #f59e0b; }
